const CONTACTS = {
  A: { warden: { name: 'Mr. Ramesh', phone: '+91 90000 00011' }, 'deputy warden': { name: 'Mr. Kiran', phone: '+91 90000 00012' } },
  B: { warden: { name: 'Mrs. Sujatha', phone: '+91 90000 00021' }, 'deputy warden': { name: 'Mr. Anil', phone: '+91 90000 00022' } },
  C: { warden: { name: 'Mrs. Lakshmi', phone: '+91 90000 00001' }, 'deputy warden': { name: 'Mr. Prasad', phone: '+91 90000 00003' } },
};
// The hostel helpdesk's contact list (made-up names and numbers).
const b = String(query.block || '').trim().toUpperCase().slice(0, 1);
return CONTACTS[b] ? JSON.stringify(CONTACTS[b]) : 'No such block. Blocks are A, B and C.';

// 🌍 Change these to change tonight's world, then chat again and watch the plan change.
const WARDEN_ANSWERS = true;            // false = the C-block warden doesn't pick up
const PLUMBER_COMES = '12:45 am';       // e.g. 'tomorrow at 9 am'

const CONTACTS = {
  A: { warden: { name: 'Mr. Ramesh', phone: '+91 90000 00011' }, 'deputy warden': { name: 'Mr. Kiran', phone: '+91 90000 00012' } },
  B: { warden: { name: 'Mrs. Sujatha', phone: '+91 90000 00021' }, 'deputy warden': { name: 'Mr. Anil', phone: '+91 90000 00022' } },
  C: { warden: { name: 'Mrs. Lakshmi', phone: '+91 90000 00001' }, 'deputy warden': { name: 'Mr. Prasad', phone: '+91 90000 00003' } },
};
const PLUMBER = '+91 90000 00002';
const digits = (p) => String(p || '').replace(/\D/g, '').slice(-10);
const msg = String(query.message || '').toLowerCase();
if (digits(query.phone) === digits(PLUMBER)) {
  if (PLUMBER_COMES.includes('tomorrow'))
    return `Ravi here. Sorry, I'm out of town tonight. I can come ${PLUMBER_COMES} and replace that pipe. Tonight, stop the water so it doesn't flood. Your handyman, Mr. Chenna Reddy, knows the levers.`;
  return `Ravi here. I'll come at ${PLUMBER_COMES} and replace the pipe. Meanwhile stop the water so the corridor doesn't flood. Your handyman, Mr. Chenna Reddy, knows the levers. Don't open the pipe yourself.`;
}
for (const block of Object.values(CONTACTS)) {
  for (const [role, person] of Object.entries(block)) {
    if (digits(person.phone) !== digits(query.phone)) continue;
    if (role === 'warden' && !WARDEN_ANSWERS) return `No answer from ${person.name}. (It's late; the phone rang out.)`;
    if (msg.includes('red')) return `${person.name}: Red stops water to the WHOLE hostel and the kitchen. Only if no smaller lever works. If it really comes to that, yes, you have my approval.`;
    return `${person.name}: Thanks for calling. The plumber is Ravi, ${PLUMBER}. Mr. Chenna Reddy, our hostel handyman, can shut the water at the valve junction. Send me an update when it's under control.`;
  }
}
return 'Wrong number. Nobody by that number.';

